mapper.select:
SELECT *
FROM (
         SELECT user_plant_id, ori_name, sys_name, url, hash
         FROM my_plant_image
         WHERE hash = #{hash}
           AND user_plant_id IN (
             SELECT user_plant_id FROM my_plant WHERE user_uid = #{userUid}
         )

         UNION ALL

         SELECT user_plant_id, ori_name, sys_name, url, hash
         FROM my_plant_image_history
         WHERE hash = #{hash}
           AND user_plant_id IN (
             SELECT user_plant_id FROM my_plant WHERE user_uid = #{userUid}
         )

         UNION ALL

         SELECT dd.user_plant_id, d.ori_name, d.sys_name, d.url, d.hash
         FROM my_plant_diary_image d
                  JOIN my_plant_diary dd ON d.diary_id = dd.diary_id
         WHERE d.hash = #{hash}
           AND dd.user_plant_id IN (
             SELECT user_plant_id FROM my_plant WHERE user_uid = #{userUid}
         )
     )
WHERE ROWNUM = 1

SELECT COUNT(*)
FROM my_plant_image
WHERE image_id = #{imageId}
  AND user_plant_id = #{userPlantId}
